INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'You have the key. The Floor Gate is at the head of the stair north of the junction, below the ledge.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Whatever guards the relic lives on the hall floor. Bring me what it carries.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 13, 1, NULL, 'DrownedReliquary3@use');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 21, 0, 1, 'DrownedReliquary2@use');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 12, 1, NULL, 'DrownedReliquary2@use');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'Use a seal on the Warded Door east of the ledge. The halls past it are full of living brine.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Take five of their cores to the dry altar in the side chamber, up the ramp at the far end. It should give you a key.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 13, 1, NULL, 'DrownedReliquary2@use');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 21, 0, 1, 'DrownedReliquary1@use');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 12, 1, NULL, 'DrownedReliquary1@use');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'The watch still stands: three Tidebound Sentinels on the ledge above the great hall.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'The portal at the far east end of the gallery takes you down to them. Show me their three seals.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 13, 1, NULL, 'DrownedReliquary1@use');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'Mind the nets. You look like someone who does not mind getting wet.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'I dive the wrecks off the north shore. Last week the tide pulled back further than I have ever seen it, and there was an arch standing in the shallows. Empyrean work.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'There is a stair inside it that goes down into the dark, and something down there crawls through the silt. It took my rope.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 10, 1, 1, 'Bring me six of the little stone votives those crawlers carry. I want to know whose shrine I have been diving on.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 4, 10, 1, 1, 'The arch is out in the shallows north of town, at 91.3N 71.2W.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 1, 1, 924100, NULL);
