INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'I have the votives already. Keep those. The seals are what I need now.');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 13, 1, NULL, 'DrownedReliquary1@votive');
