INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Temple votives. Each one has a name cut in the base, and the names are a watch roster.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'The watch still stands, then. The Empyreans set stone guards on the ledge above the great hall, and the sea has not finished them.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 10, 1, 1, 'Break three of those Tidebound Sentinels and bring me their seals. The portal at the far east end of the gallery goes down to the ledge.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 4, 22, 0, 1, 'DrownedReliquary1');
INSERT INTO weenie_properties_emote (object_Id, category, probability, weenie_Class_Id, quest) VALUES (924120, 23, 1, NULL, 'DRVotives');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'Six votives, friend. Count them again.');
