INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 0, 10, 0, 1, 'Three seals. Hold on to them. The Warded Door east of the ledge answers to any one of them.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 1, 10, 1, 1, 'Past it the halls are full of living brine. Take five of their cores to the dry altar in the side chamber, up the ramp at the far end.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 2, 10, 1, 1, 'If the old stories are true, the altar will give you a key to the great hall floor.');
INSERT INTO weenie_properties_emote_action (emote_Id, `order`, type, delay, extent, message) VALUES (@e, 3, 22, 0, 1, 'DrownedReliquary2');
